(x, y, t) => {
  const cx = 240, cy = 120;
  const w1 = Math.sin(x*0.013+t*0.4)*Math.cos(y*0.011-t*0.3)*22;
  const w2 = Math.cos(x*0.009-t*0.25)*Math.sin(y*0.016+t*0.35)*18;
  const w3 = Math.sin((x+y)*0.008+t*0.5)*12;
  const wx = Math.sin(x*0.02+t*0.3)*14 + Math.cos(y*0.015-t*0.2)*10 + w1;
  const wy = Math.cos(y*0.02-t*0.25)*14 + Math.sin(x*0.018+t*0.35)*10 + w2 + w3;
  const sx = x + wx, sy = y + wy;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [200+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*90,0.11,2.1],
    [300+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.45+4)*50,0.085,1.8]
  ];
  let aS=0,iS=0,aS2=0,iS2=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp); iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aS2+=Math.sin(d*f*1.5-t*sp*1.3+0.7); iS2+=Math.sin(d*f*1.2+t*sp*0.9+2.8);
  }
  const n=8, act=aS/n, inh=iS/n, act2=aS2/n, inh2=iS2/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.06+sy*0.04+t*0.7)*0.12;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    +Math.sin(dist*0.03-ang*5+t*0.8)*0.2;
  const r1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const r2=Math.tanh((act2-inh2*0.6+r1*0.4+spiral*0.5)*2.0);
