  const dwx=sx+comb*14, dwy=sy+r2*11;
  const detail=(Math.sin(dwx*0.22)*Math.cos(dwy*0.22)+Math.sin(dwx*0.16+dwy*0.16+t*1.5))*0.12;
  const dwx2=dwx+detail*8, dwy2=dwy-detail*6;
  const micro=(Math.sin(dwx2*0.35+t*2)*Math.cos(dwy2*0.3-t*1.7))*0.06;
  const blend=comb*0.6+cell*0.2+detail*0.12+micro*0.08;
  const v=blend*0.5+0.5;
  const pal=[
    [4,8,48],[8,32,78],[12,68,108],[18,110,125],[30,148,118],
    [80,172,95],[150,192,60],[210,188,42],[232,155,38],
    [218,105,42],[195,60,48],[145,35,55],[85,22,52],[35,14,50],[4,8,48]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const sf=f*f*(3-2*f);
  const lum=0.72+Math.sin(comb*Math.PI)*0.28;
  const edge=Math.abs(comb)>0.6?1.0+(Math.abs(comb)-0.6)*0.7:1.0;
  const vig=1.0-dist*0.0007;
  const spec=Math.max(0,comb-0.45)*0.35;
  const fl=lum*edge*vig;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*fl+spec*255)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*fl+spec*210)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*fl+spec*160)|0)
  ];
}
